function run_exp14_sps_validation()
root=fileparts(mfilename('fullpath'));old=pwd;c=onCleanup(@()cd(old));cd(root);warning('off','all');d=make_exp14_settings();model=fullfile(root,'generated',[d.model_name '.slx']);if ~exist(model,'file'),build_exp14_dab_model();end;load_system(model);tsim=tic;out=sim(d.model_name);simulation_time_s=toc(tsim);close_system(d.model_name,0);
sig={'p_vac','p_iac','p_vdc','p_idc','s_vac','s_iac','s_vdc','s_idc'};for k=1:numel(sig),x=out.get([sig{k} '_exp14']);t=x.time;y.(sig{k})=x.signals.values;end
keep=t>=d.discard_cycles*d.Ts;tt=t(keep);Pp=trapz(tt,y.p_vac(keep).*y.p_iac(keep))/(tt(end)-tt(1));Ps=trapz(tt,y.s_vac(keep).*y.s_iac(keep))/(tt(end)-tt(1));loss=-(Pp+Ps);bp=max(abs(y.p_vdc.*y.p_idc+y.p_vac.*y.p_iac));bs=max(abs(y.s_vdc.*y.s_idc+y.s_vac.*y.s_iac));peak_ip=max(abs(y.p_iac(keep)));peak_is=max(abs(y.s_iac(keep)));
res=fullfile(root,'..','results');fig=fullfile(root,'..','figures');if ~exist(res,'dir'),mkdir(res);end;if ~exist(fig,'dir'),mkdir(fig);end;T=table(Pp,Ps,loss,peak_ip,peak_is,bp,bs,simulation_time_s,'VariableNames',{'primary_bridge_ac_absorbed_W','secondary_bridge_ac_absorbed_W','winding_absorbed_loss_W','primary_peak_current_A','secondary_peak_current_A','primary_bridge_power_residual_W','secondary_bridge_power_residual_W','simulation_time_s'});writetable(T,fullfile(res,'sps_validation_summary.csv'));save(fullfile(res,'sps_waveforms.mat'),'t','y','d','T');
f=figure('Visible','off','Position',[100 100 1100 760]);subplot(3,1,1);plot(tt*1e3,y.p_vac(keep),tt*1e3,y.s_vac(keep));ylabel('v_{ac} (V)');legend('primary','secondary');grid on;subplot(3,1,2);plot(tt*1e3,y.p_iac(keep),tt*1e3,y.s_iac(keep));ylabel('i_{ac} (A)');legend('primary','secondary');grid on;subplot(3,1,3);plot(tt*1e3,y.p_vac(keep).*y.p_iac(keep),tt*1e3,y.s_vac(keep).*y.s_iac(keep));ylabel('p_{absorbed} (W)');xlabel('time (ms)');grid on;exportgraphics(f,fullfile(fig,'sps_switching_regression_waveforms.png'),'Resolution',180);close(f);fprintf('EXP14_SIM_OK Pp_abs=%.6f Ps_abs=%.6f windingLoss=%.6f peakI=[%.3f %.3f] bridgeResidual=[%.3e %.3e]\n',Pp,Ps,loss,peak_ip,peak_is,bp,bs);
end
